'use client';

import { useState } from 'react';
import { Clock } from 'lucide-react';
import { KDSOrder } from '../../types/kds';
import { SourceBadge } from './SourceBadge';
import { DelayOrderModal } from '../modals/DelayOrderModal';
import { CustomerMessagingModal } from '../modals/CustomerMessagingModal';
import { useKDSStore } from '../../store/kdsStore';
import { TicketTimer } from './TicketTimer';
import { useKDSSound } from '../sound/useKDSSound';
import { useAuth } from '@/app/providers/AuthProvider';
import { KDSRole, canDelayOrder, canCancelOrder } from '../../utils/kdsAccess';
import { isMessagingModuleActive } from '../../utils/kdsModuleFlags';
import { resolveAllModifiers } from '../../utils/kdsModifierRenderer';

interface Props {
    order: KDSOrder;
    variant?: 'standard' | 'expo';
}

export function OrderTicket({ order, variant = 'standard' }: Props) {
    const [isDelayModalOpen, setIsDelayModalOpen] = useState(false);
    const [isMessagingModalOpen, setIsMessagingModalOpen] = useState(false);
    const [isProcessing, setIsProcessing] = useState(false);
    const [isThrottled, setIsThrottled] = useState(false);
    const [isDelayThrottled, setIsDelayThrottled] = useState(false);
    const { delayOrder, advanceStage, acceptOrder, incrementPrepTime, sendCustomerMessage, cancelOrder } = useKDSStore();
    const { playSound } = useKDSSound();
    const { role: authRole, enabledModules } = useAuth();

    // Permissions & Module Enforcement
    const role = (authRole as KDSRole) || 'KDS_USER';
    const isMessagingActive = isMessagingModuleActive({ module4: enabledModules.includes('messaging') || true });

    // Production visual states logic
    const getBorderState = () => {
        if (order.isDelayed) return 'border-red-600 border-[4px]';
        if (order.stage === 'READY') return 'border-green-500 border-[4px]';
        if (order.stage === 'CUTTING') return 'border-purple-500 border-[4px]';
        if (order.stage === 'PREPARATION') return 'border-[#1FA4A9] border-[4px]';
        return 'border-slate-200 border-[1px]';
    };

    const handleAdvance = async () => {
        if (isProcessing) return;
        setIsProcessing(true);

        // Sound confirmation
        playSound('ORDER_UPDATED', order.id);

        // Mock delay for visual transition - allow time for slide-out animation if any
        setTimeout(() => {
            advanceStage(order.id);
            setIsProcessing(false);
        }, 300);
    };

    const handleDelayConfirm = (minutes: number, reason?: string) => {
        if (isDelayThrottled) return;

        delayOrder(order.id, minutes, role, reason);
        setIsDelayThrottled(true);
        setTimeout(() => setIsDelayThrottled(false), 3000);

        // Trigger delay sound
        playSound('ORDER_DELAYED', order.id);
    };

    const handleCancel = () => {
        if (window.confirm('Are you sure you want to cancel this order?')) {
            cancelOrder(order.id, role);
            playSound('ORDER_CANCELLED', order.id);
        }
    };

    const formatCreatedAt = (dateStr: string) => {
        try {
            const date = new Date(dateStr);
            return date.toLocaleTimeString('en-US', {
                hour: '2-digit',
                minute: '2-digit',
                hour12: false
            });
        } catch {
            return '--:--';
        }
    };

    const formatETA = (value: string | undefined) => {
        if (!value) return '--:--';
        // Handle ISO strings
        if (value.includes('T')) {
            try {
                return new Date(value).toLocaleTimeString('en-US', {
                    hour: '2-digit',
                    minute: '2-digit',
                    hour12: false
                });
            } catch {
                return '--:--';
            }
        }
        return value; // Already formatted
    };

    const handleAccept = async () => {
        if (isProcessing) return;
        setIsProcessing(true);

        playSound('ORDER_UPDATED', order.id);

        setTimeout(() => {
            acceptOrder(order.id);
            setIsProcessing(false);
        }, 300);
    };

    const handleIncrementPrep = () => {
        if (isThrottled) return;

        setIsThrottled(true);
        incrementPrepTime(order.id, 5);

        // Visual feedback sound
        playSound('ORDER_UPDATED', order.id);

        setTimeout(() => {
            setIsThrottled(false);
        }, 800);
    };

    const getActionButton = () => {
        const isReady = order.stage === 'READY';
        const isAccepted = order.stage === 'ACCEPTED';
        const isPrep = order.stage === 'PREPARATION';

        const plusFiveBtn = !isReady && (
            <button
                disabled={isThrottled}
                onClick={handleIncrementPrep}
                className="flex-none px-4 bg-slate-200 text-slate-800 h-[60px] rounded-xl font-black text-sm hover:bg-slate-300 transition-all border-2 border-slate-300 disabled:opacity-50"
            >
                +5 Min
            </button>
        );

        if (variant === 'expo') {
            return (
                <div className="flex gap-2">
                    {plusFiveBtn}
                    <button
                        onClick={() => {
                            // Placeholder for print label
                            alert(`Printing label for #${order.orderNumber}`);
                        }}
                        className="flex-1 bg-slate-200 text-slate-800 h-[60px] rounded-xl font-black uppercase tracking-widest text-xs hover:bg-slate-300 transition-all border-2 border-slate-300"
                    >
                        Print Label
                    </button>
                    <button
                        disabled={isProcessing}
                        onClick={handleAdvance}
                        className="flex-[2] bg-slate-900 text-white h-[60px] rounded-xl font-black uppercase tracking-widest text-sm hover:bg-slate-800 active:scale-[0.98] transition-all disabled:opacity-50 shadow-lg"
                    >
                        {isProcessing ? 'Saving...' : (isReady ? 'Mark Completed' : 'Mark Completed')}
                    </button>
                </div>
            );
        }

        // Standard variant
        let mainActionLabel = 'Next Stage';
        let mainActionColor = 'bg-purple-600';
        let mainActionHandler = handleAdvance;

        if (isAccepted) {
            mainActionLabel = 'Start Preparation';
            mainActionColor = 'bg-[#1FA4A9]';
            mainActionHandler = handleAccept;
        } else if (isReady) {
            mainActionLabel = 'Mark Completed';
            mainActionColor = 'bg-slate-900';
        } else if (isPrep) {
            mainActionColor = 'bg-slate-950';
        }

        return (
            <div className="flex gap-2">
                {plusFiveBtn}
                <button
                    disabled={isProcessing}
                    onClick={mainActionHandler}
                    className={`flex-1 h-[60px] rounded-xl font-black uppercase tracking-widest text-sm hover:brightness-110 active:scale-[0.98] transition-all disabled:opacity-50 shadow-lg text-white ${mainActionColor}`}
                >
                    {isProcessing ? 'Processing...' : mainActionLabel}
                </button>
            </div>
        );
    };

    const getFulfillmentStyle = () => {
        if (variant !== 'expo') return 'bg-slate-100 text-slate-700';

        const type = order.fulfillment_type;
        if (type.includes('DELIVERY')) {
            return 'bg-amber-100 text-amber-700 border border-amber-200';
        }
        return 'bg-blue-100 text-blue-700 border border-blue-200';
    };

    const isUberDirect = order.order_source === 'UBER_DIRECT';

    return (
        <>
            <div
                className={`kds-ticket bg-white rounded-xl shadow-xl flex flex-col overflow-hidden transition-all duration-500 kds-animate-in ${getBorderState()} ${isProcessing ? 'opacity-50 translate-x-4 grayscale-[0.2]' : ''} ${variant === 'expo' ? 'min-h-[450px] w-full max-w-[600px] mx-auto' : 'min-h-[280px]'} ${isUberDirect ? 'border-l-[6px] border-l-black' : ''}`}
            >
                {/* TOP ROW */}
                <div className={`p-4 border-bottom border-slate-100 flex justify-between items-start ${variant === 'expo' ? 'bg-slate-900 text-white' : 'bg-slate-50'}`}>
                    <div className="flex flex-col gap-1">
                        <h2 className={`font-black tracking-tighter ${variant === 'expo' ? 'text-[42px]' : 'text-[28px] leading-tight text-slate-950'}`}>
                            #{order.orderNumber}
                        </h2>
                        <div className="flex items-center gap-2">
                            <SourceBadge source={order.order_source} />
                            {order.isDelayed && (
                                <span className="bg-red-600 text-white text-[10px] font-black px-2 py-0.5 rounded uppercase animate-pulse">
                                    Delayed
                                </span>
                            )}
                            {order.isPendingSync && (
                                <div className="flex items-center gap-1 bg-amber-100 text-amber-700 text-[10px] font-black px-2 py-0.5 rounded uppercase border border-amber-200" title="Pending sync">
                                    <Clock size={10} />
                                    <span>Syncing</span>
                                </div>
                            )}
                            {variant !== 'expo' && order.stage !== 'READY' && (
                                <div className="flex items-center gap-1">
                                    {canDelayOrder(role) && (
                                        <button
                                            disabled={isDelayThrottled}
                                            onClick={() => setIsDelayModalOpen(true)}
                                            className="text-[10px] font-black uppercase text-red-500 hover:bg-red-50 px-2 py-1 rounded transition-all disabled:opacity-50"
                                        >
                                            Mark Delayed
                                        </button>
                                    )}
                                    {canCancelOrder(role) && (
                                        <button
                                            onClick={handleCancel}
                                            className="text-[10px] font-black uppercase text-slate-400 hover:text-red-600 hover:bg-red-50 px-2 py-1 rounded transition-all"
                                        >
                                            Cancel
                                        </button>
                                    )}
                                </div>
                            )}
                            {isMessagingActive && order.stage !== 'READY' && (
                                <button
                                    onClick={() => setIsMessagingModalOpen(true)}
                                    className="text-[10px] font-black uppercase text-[#1FA4A9] hover:bg-[#1FA4A9]/5 px-2 py-1 rounded transition-all"
                                >
                                    Send Message
                                </button>
                            )}
                        </div>
                    </div>
                    <div className="text-right">
                        <span className={`text-xs font-bold uppercase tracking-tighter ${variant === 'expo' ? 'text-slate-400' : 'text-slate-400'}`}>
                            CREATED: {formatCreatedAt(order.createdAt)}
                        </span>
                    </div>
                </div>

                {/* SECOND ROW */}
                <div className={`px-4 py-2 flex justify-between items-center border-y border-slate-200 ${getFulfillmentStyle()}`}>
                    <span className="text-sm font-black uppercase tracking-widest">
                        {order.fulfillment_type.replace(/_/g, ' ')}
                    </span>
                    <span className={`px-2 py-0.5 text-white text-[10px] font-black rounded uppercase tracking-widest ${variant === 'expo' ? 'bg-green-600' : 'bg-slate-800'}`}>
                        {order.stage}
                    </span>
                </div>

                {/* MIDDLE SECTION - ITEM LIST */}
                <div className="p-4 flex-1 overflow-y-auto max-h-[400px]">
                    <div className="space-y-4">
                        {order.items.map((item, idx) => (
                            <div key={idx} className="border-b border-slate-50 last:border-0 pb-3 last:pb-0">
                                <div className="flex items-start gap-2">
                                    <span className="text-[20px] font-black text-slate-900 leading-none mt-1">
                                        1x
                                    </span>
                                    <div className="flex flex-col">
                                        <span className="text-[20px] font-bold text-slate-900 leading-tight">
                                            {item.name}
                                        </span>
                                        {item.variant && (
                                            <span className="text-sm font-semibold text-slate-500 italic">
                                                {item.variant}
                                            </span>
                                        )}
                                    </div>
                                </div>

                                {/* Modifiers — hardened group_type rendering */}
                                {item.modifiers.length > 0 && (() => {
                                    const resolved = resolveAllModifiers(item.modifiers);
                                    return (
                                        <div className="ml-8 mt-2 space-y-1">
                                            {resolved.map((mod, modIdx) => (
                                                <div key={modIdx} className="flex items-center gap-1.5 flex-wrap">

                                                    {/* Bullet */}
                                                    <span className={`text-sm font-black leading-none ${mod.hasDataError ? 'text-rose-500' : 'text-blue-500'
                                                        }`}>+</span>

                                                    {/* QUANTITY_ONLY: show qty prefix */}
                                                    {mod.resolvedQuantity !== null && (
                                                        <span className="text-[11px] font-black bg-slate-800 text-white px-1.5 py-0.5 rounded leading-none tabular-nums">
                                                            ×{mod.resolvedQuantity}
                                                        </span>
                                                    )}

                                                    {/* Modifier name */}
                                                    <span className={`flex-1 text-md font-bold leading-tight ${mod.hasDataError ? 'text-rose-700' : 'text-slate-600'
                                                        }`}>
                                                        {mod.name}
                                                    </span>

                                                    {/* PLACEMENT_TOPPING: placement chip (never inferred — FULL is only default) */}
                                                    {mod.resolvedPlacement !== null && !mod.hasDataError && (
                                                        <span className="text-[9px] px-1.5 py-0.5 bg-slate-200 text-slate-600 rounded uppercase font-black tracking-tighter shrink-0">
                                                            {mod.resolvedPlacement}
                                                        </span>
                                                    )}

                                                    {/* Data error badge (CHOICE_ONE multi-select / unknown type) */}
                                                    {mod.hasDataError && mod.dataErrorMessage && (
                                                        <span
                                                            className="text-[9px] px-1.5 py-0.5 bg-rose-100 text-rose-700 border border-rose-200 rounded font-black uppercase tracking-tighter shrink-0"
                                                            title={mod.dataErrorMessage}
                                                        >
                                                            {mod.isUnknownGroupType ? '⚠ UNKNOWN TYPE' : '⚠ DATA ERR'}
                                                        </span>
                                                    )}

                                                </div>
                                            ))}
                                        </div>
                                    );
                                })()}
                            </div>
                        ))}
                    </div>
                </div>

                {/* BOTTOM SECTION */}
                <div className="p-4 mt-auto border-t border-slate-200 bg-slate-50 flex flex-col gap-3">
                    {/* External vs Zyappy Total Comparison (Compliance) */}
                    {order.externalTotal !== undefined && order.zyappyCalculatedTotal !== undefined && (
                        <div className="mb-1 flex flex-col gap-1 py-1.5 px-3 bg-white rounded-lg border border-slate-200 shadow-sm">
                            <div className="flex justify-between items-center">
                                <span className="text-[9px] font-black uppercase text-slate-400">External Charged</span>
                                <span className="text-xs font-black text-slate-900 tracking-tight">₹{order.externalTotal}</span>
                            </div>
                            <div className="flex justify-between items-center">
                                <span className="text-[9px] font-black uppercase text-slate-400">Zyappy Calculated</span>
                                <div className="flex items-center gap-1">
                                    <span className="text-xs font-black text-slate-900 tracking-tight">₹{order.zyappyCalculatedTotal}</span>
                                    {order.externalTotal !== order.zyappyCalculatedTotal && (
                                        <div
                                            className="text-amber-500 cursor-help flex items-center justify-center p-0.5"
                                            title="Price difference detected"
                                        >
                                            <span className="text-[12px] leading-none">⚠️</span>
                                        </div>
                                    )}
                                </div>
                            </div>
                        </div>
                    )}

                    <div className="flex justify-between items-center">
                        <div className="flex flex-col">
                            <div className="flex items-center gap-1.5">
                                <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">EST. READY</span>
                                {order.prepTimeMinutes > 0 && (
                                    <span className="text-[9px] font-black text-slate-500 bg-slate-200 px-1.5 py-0.5 rounded leading-none uppercase">
                                        Prep: {order.prepTimeMinutes} min
                                    </span>
                                )}
                            </div>
                            <span className="text-xl font-black text-slate-800 tracking-tight">
                                {formatETA(order.estimatedReadyTime)}
                            </span>
                            {order.isDelayed && order.delayReason && (
                                <span className="text-[10px] font-bold text-red-600 italic leading-tight max-w-[150px] truncate">
                                    {order.delayReason}
                                </span>
                            )}
                        </div>
                        <TicketTimer createdAt={order.createdAt} prepTimeMinutes={order.prepTimeMinutes} />
                    </div>

                    {getActionButton()}
                </div>
            </div >

            <DelayOrderModal
                isOpen={isDelayModalOpen}
                onClose={() => setIsDelayModalOpen(false)}
                onConfirm={handleDelayConfirm}
                orderNumber={order.orderNumber}
            />

            <CustomerMessagingModal
                isOpen={isMessagingModalOpen}
                order={order}
                onClose={() => setIsMessagingModalOpen(false)}
                onSend={(channel, message) => {
                    if (isMessagingActive) {
                        sendCustomerMessage(order.id, channel, message);
                    }
                }}
                role={role}
            />
        </>
    );
}
