'use client';

import { useEffect } from 'react';
import { useShallow } from 'zustand/react/shallow';
import { KDSHeader } from '@/modules/kds/components/KDSHeader';
import { OrderTicket } from '@/modules/kds/components/ticket/OrderTicket';
import { useKDSStore } from '@/modules/kds/store/kdsStore';
import { FulfillmentType } from '@/modules/kds/types/kds';

import { useFilterStore } from '@/modules/kds/store/useFilterStore';

export default function KDSExpoPage() {
    const { fulfillment: filter, source: currentSource, setFulfillment: setFilter } = useFilterStore();
    const { addOrUpdateOrder } = useKDSStore();

    useEffect(() => {
        const hasReady = Object.values(useKDSStore.getState().orders).some(o => o.stage === 'READY');
        if (!hasReady) {
            // Inject Pickup Ready
            addOrUpdateOrder({
                id: 'expo-mock-1',
                orderNumber: '5001',
                order_source: 'POS',
                fulfillment_type: 'PICKUP',
                createdAt: new Date(Date.now() - 1000 * 60 * 15).toISOString(),
                updatedAt: new Date().toISOString(),
                stage: 'READY',
                prepTimeMinutes: 10,
                estimatedReadyTime: '12:00',
                isDelayed: false,
                trackingToken: 'token-5001',
                items: [{ name: 'Expo Burger', modifiers: [] }]
            });
            // Inject Delivery Ready
            addOrUpdateOrder({
                id: 'expo-mock-2',
                orderNumber: '5002',
                order_source: 'ONLINE',
                fulfillment_type: 'STORE_DELIVERY',
                createdAt: new Date(Date.now() - 1000 * 60 * 20).toISOString(),
                updatedAt: new Date().toISOString(),
                stage: 'READY',
                prepTimeMinutes: 15,
                estimatedReadyTime: '12:10',
                isDelayed: false,
                trackingToken: 'token-5002',
                items: [{ name: 'SaaS Pizza', modifiers: [] }]
            });
        }
    }, [addOrUpdateOrder]);

    // Subscribe to READY orders only
    const orders = useKDSStore(useShallow((state) =>
        Object.values(state.orders).filter(o =>
            o.stage === 'READY' &&
            (filter === 'ALL' || o.fulfillment_type === filter) &&
            (currentSource === 'ALL' || o.order_source === currentSource)
        ).sort((a, b) => new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime())
    ));

    const fulfillmentTypes: (FulfillmentType | 'ALL')[] = [
        'ALL',
        'PICKUP',
        'STORE_DELIVERY',
        'UBER_DIRECT_DELIVERY'
    ];

    return (
        <div className="flex flex-col h-screen overflow-hidden bg-slate-50 shadow-2xl">
            <KDSHeader />

            <div className="bg-white border-b border-slate-200 px-6 py-4 flex items-center justify-between shadow-sm">
                <div className="flex flex-col">
                    <h1 className="text-xl font-black text-slate-900 uppercase tracking-widest">Expo Display</h1>
                    <span className="text-[10px] font-bold text-slate-400 uppercase tracking-tighter">Consolidated Ready Orders</span>
                </div>

                <div className="flex items-center gap-2">
                    {fulfillmentTypes.map((type) => (
                        <button
                            key={type}
                            onClick={() => setFilter(type)}
                            className={`px-4 py-2 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all ${filter === type
                                ? 'bg-slate-900 text-white shadow-lg scale-105'
                                : 'bg-slate-100 text-slate-500 hover:bg-slate-200'
                                }`}
                        >
                            {type.replace(/_/g, ' ')}
                        </button>
                    ))}
                </div>

                <div className="bg-slate-900 text-white px-4 py-2 rounded-lg">
                    <span className="text-sm font-black tracking-widest">{orders.length} READY</span>
                </div>
            </div>

            <main className="flex-1 overflow-y-auto p-8 bg-slate-100/50">
                {orders.length === 0 ? (
                    <div className="h-full flex flex-col items-center justify-center text-slate-400 opacity-50">
                        <div className="w-24 h-24 mb-4 border-4 border-dashed border-slate-300 rounded-full animate-spin duration-[10000ms]" />
                        <span className="text-lg font-black uppercase tracking-[0.2em]">No Ready Orders</span>
                    </div>
                ) : (
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-8 animate-in fade-in duration-500">
                        {orders.map((order) => (
                            <OrderTicket
                                key={order.id}
                                order={order}
                                variant="expo"
                            />
                        ))}
                    </div>
                )}
            </main>
        </div>
    );
}
